        require(rows.map {it.packageName}.distinct().size==rows.size)
        rows.forEach {RouteRules.validatePackage(it.packageName);require(it.name.isNotBlank()&&it.category.isNotBlank()&&validPrimaryUrl(it.packageName,it.primaryUrl)&&validProvenance(it.packageName,it.provenance))}
    }
    val byPackage:Map<String,Item> = items.associateBy {it.packageName}
    fun installed(packages:Set<String>):List<Item> = items.filter {it.packageName in packages}
    fun validPrimaryUrl(packageName:String,url:String):Boolean {
        // The store itself is distributed directly; its official SDK FAQ binds
        // this exact package identity, not an inferred/nonexistent store listing.
        if(packageName=="ru.vk.store"&&url=="https://www.rustore.ru/help/sdk/payments/faq")return true
        if(url=="https://www.rustore.ru/catalog/app/"+packageName)return true
        return runCatching {
            val uri=java.net.URI(url)
            if(uri.scheme!="https"||uri.host!="play.google.com"||uri.rawUserInfo!=null||uri.port!=-1||uri.rawFragment!=null||uri.rawPath!="/store/apps/details")return@runCatching false
            val parts=uri.rawQuery?.split('&')?:return@runCatching false
            parts.size in 1..2&&parts.count {it=="id=$packageName"}==1&&parts.all {it=="id=$packageName"||it=="hl=ru"}
        }.getOrDefault(false)
    }
    fun validProvenance(packageName:String,url:String):Boolean {
        if(validPrimaryUrl(packageName,url))return true
        return runCatching {
            val uri=java.net.URI(url)
            uri.scheme=="https"&&uri.host=="www.rustore.ru"&&uri.rawUserInfo==null&&uri.port==-1&&uri.rawQuery==null&&uri.rawFragment==null&&(
                uri.rawPath in setOf("/catalog/finance","/catalog/social","/catalog/state","/catalog/purchases")||
                Regex("/catalog/developer/[A-Za-z0-9_-]+(?:/page-[1-9][0-9]*)?").matches(uri.rawPath)||
                Regex("/catalog/featuring/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}").matches(uri.rawPath)
            )
        }.getOrDefault(false)
    }
    // Brand spellings refer to the same verified package, never additional app identities.
    private val searchAliases=mapOf(
        "ru.oneme.app" to "MAX МАКС",
        "ru.kfc.kfc_delivery" to "KFC КФС Ростикс Rostics",
        "ru.dostaevsky.android" to "Достаевский Dostaevsky",
        "ru.chibbis" to "Chibbis",
        "com.broniboy.client" to "Бронибой",
        "com.mobilemedia.tanuki" to "Тануки",
        "ru.utair.android" to "Utair Ютэйр",
        "youdrive.today" to "Citydrive YouDrive Ситидрайв",
        "com.bearsdev.cseapp" to "КСЭ CSE",
        "ru.apteka" to "Аптека ру Аптека.ру",
        "com.invitro.app" to "Инвитро",
        "ru.helix.express" to "Хеликс Экспресс",
        "ru.mts.smartmed" to "СмартМед"
    )
    fun matches(item:Item,installedLabel:String,query:String):Boolean {
        val q=query.trim().lowercase(java.util.Locale.ROOT)
        val aliases=searchAliases[item.packageName].orEmpty()
        return q.isEmpty()||"${item.name} $installedLabel ${item.category} $aliases".lowercase(java.util.Locale.ROOT).contains(q)
    }
}
